class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        unordered_set<int> seen;
        for (int i = nums.size() - 1; i >= 0; --i) {
            if (nums[i] <= k) seen.insert(nums[i]);
            if ((int)seen.size() == k) return nums.size() - i;
        }
        return nums.size();
    }
};

